export class SoundEngine {
  private ctx: AudioContext | null = null;
  private initialized = false;
  private isMiniGame = false;

  init() {
    if (this.initialized) return;
    
    // 检测是否在微信小游戏环境
    this.isMiniGame = typeof wx !== 'undefined' && wx.createInnerAudioContext;
    
    if (this.isMiniGame) {
      // 微信小游戏环境，使用 InnerAudioContext
      this.initialized = true;
      return;
    }
    
    // H5/小程序环境，使用 Web Audio API
    try {
      const Ctor = (window as any).AudioContext || (window as any).webkitAudioContext;
      if (Ctor) {
        this.ctx = new Ctor();
        this.initialized = true;
      }
    } catch {
      console.warn('[Sound] Web Audio API not available');
    }
  }

  resume() {
    if (this.isMiniGame) return;
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  private playTone(freq: number, duration: number, type: OscillatorType = 'square', volume = 0.06) {
    if (this.isMiniGame) {
      // 微信小游戏使用简单的 beep 效果（通过短音频）
      this.playMiniGameBeep(freq, duration);
      return;
    }
    
    if (!this.ctx) return;
    this.resume();
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.connect(g);
    g.connect(this.ctx.destination);
    o.frequency.setValueAtTime(freq, this.ctx.currentTime);
    g.gain.setValueAtTime(volume, this.ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + duration);
    o.start();
    o.stop(this.ctx.currentTime + duration);
  }

  private playMiniGameBeep(_freq: number, duration: number) {
    // 微信小游戏：使用短促的音频文件或系统音效
    // 由于无法实时合成，这里使用简单的点击音效替代
    // 实际项目中可以准备预制的音效文件
    try {
      const audio = wx.createInnerAudioContext();
      audio.src = ''; // 可以配置为预制音效文件路径
      audio.volume = 0.3;
      audio.play();
      
      // 自动销毁
      setTimeout(() => {
        audio.destroy();
      }, duration * 1000 + 100);
    } catch (e) {
      // 静默失败，不影响游戏体验
    }
  }

  private playFreqs(freqs: number[], durations: number[], type: OscillatorType = 'square', volume = 0.06) {
    if (this.isMiniGame) {
      // 微信小游戏简化处理
      return;
    }
    
    if (!this.ctx) return;
    this.resume();
    let t = this.ctx.currentTime;
    for (let i = 0; i < freqs.length; i++) {
      const o = this.ctx.createOscillator();
      const g = this.ctx.createGain();
      o.type = type;
      o.connect(g);
      g.connect(this.ctx.destination);
      o.frequency.setValueAtTime(freqs[i], t);
      g.gain.setValueAtTime(volume, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + durations[i]);
      o.start(t);
      o.stop(t + durations[i]);
      t += durations[i];
    }
  }

  shoot() {
    this.playTone(800, 0.08);
  }

  explosion() {
    this.playTone(100, 0.2, 'sawtooth', 0.08);
    this.playTone(60, 0.3, 'sawtooth', 0.06);
  }

  powerup() {
    this.playFreqs([600, 800, 1000], [0.08, 0.08, 0.1], 'square', 0.05);
  }

  gameOver() {
    this.playFreqs([400, 300, 200, 100], [0.2, 0.2, 0.2, 0.4], 'square', 0.06);
  }

  levelComplete() {
    this.playFreqs([400, 500, 600, 800], [0.1, 0.1, 0.1, 0.2], 'square', 0.05);
  }

  hit() {
    this.playTone(300, 0.1, 'triangle', 0.04);
  }

  superShoot() {
    this.playTone(1000, 0.1, 'sine', 0.05);
    this.playTone(1200, 0.08, 'sine', 0.04);
  }

  play(type: 'shoot' | 'explosion' | 'powerup' | 'gameOver' | 'levelComplete' | 'hit' | 'superShoot') {
    switch (type) {
      case 'shoot': this.shoot(); break;
      case 'explosion': this.explosion(); break;
      case 'powerup': this.powerup(); break;
      case 'gameOver': this.gameOver(); break;
      case 'levelComplete': this.levelComplete(); break;
      case 'hit': this.hit(); break;
      case 'superShoot': this.superShoot(); break;
    }
  }
}

export const sound = new SoundEngine();
